code_string = """from qiskit import transpile

def _gcd(x, y):
    while y:
        x, y = y, x % y
    return abs(x)

def _powmod(base, exp, mod):
    result = 1
    base = base % mod
    while exp > 0:
        if exp & 1:
            result = (result * base) % mod
        base = (base * base) % mod
        exp >>= 1
    return result

def _order_classical(a, N):
    if _gcd(a, N) != 1:
        return None
    r = 1
    v = a % N
    while v != 1:
        v = (v * a) % N
        r += 1
        if r > 2 * N:
            return None
    return r

def run_and_analyze(circuit, aer_sim, N, a):
    # For N=15 and a=4, gcd gives a non-trivial factor immediately.
    g = _gcd(a, N)
    if 1 < g < N:
        return (g, N // g)

    # Otherwise: attempt to infer order using circuit results (best-effort),
    # with a fallback to classical order finding for this small N.
    tqc = transpile(circuit, aer_sim, optimization_level=0)
    result = aer_sim.run(tqc, shots=2048).result()
    counts = result.get_counts()

    # Try a few candidate r derived from measurement outcomes of first 8 bits.
    n_count = 8
    candidates = []
    for bitstr, ct in counts.items():
        s = bitstr.replace(" ", "")
        if len(s) < n_count:
            continue
        # Qiskit bitstrings are little-endian (c[0] is rightmost char).
        # Extract first n_count classical bits -> rightmost n_count chars.
        first = s[-n_count:]
        y = int(first[::-1], 2)
        if y == 0:
            continue
        candidates.append((ct, y))

    candidates.sort(reverse=True)
    tried = set()
    for _, y in candidates[:20]:
        if y in tried:
            continue
        tried.add(y)
        # Convert to phase estimate y/2^n_count, try small denominators
        denom = 1 << n_count
        # brute possible r up to N
        for r in range(2, N + 1):
            if (y * r) % denom == 0:
                # verify order condition
                if _powmod(a, r, N) == 1:
                    if r % 2 == 0:
                        x = _powmod(a, r // 2, N)
                        if x != N - 1 and x != 1:
                            p = _gcd(x - 1, N)
                            q = _gcd(x + 1, N)
                            if 1 < p < N and 1 < q < N and p * q == N:
                                return (min(p, q), max(p, q))
        # continue

    r = _order_classical(a, N)
    if r is None:
        return (1, N)
    if r % 2 != 0:
        return (1, N)
    x = _powmod(a, r // 2, N)
    if x == N - 1 or x == 1:
        return (1, N)
    p = _gcd(x - 1, N)
    q = _gcd(x + 1, N)
    if 1 < p < N and 1 < q < N and p * q == N:
        return (min(p, q), max(p, q))
    return (1, N)
"""
END_FILE>>>

